CREATE TABLE public.season_quests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES public.trips(id) ON DELETE CASCADE, user_id uuid NOT NULL, quest_kind text NOT NULL CHECK (quest_kind IN ('preflight','carry_on')), night_week integer, title text NOT NULL, mission_text text NOT NULL, backstory text NOT NULL, keywords text[] NOT NULL, points integer NOT NULL CHECK (points BETWEEN 0 AND 12), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','pending','approved','declined')), presented_at timestamptz, approved_at timestamptz, approved_by uuid, awarded_points integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((quest_kind='preflight' AND night_week>0) OR (quest_kind='carry_on' AND night_week IS NULL)), CHECK ((status='approved')=(approved_at IS NOT NULL AND approved_by IS NOT NULL AND awarded_points IS NOT NULL)), CHECK (awarded_points IS NULL OR awarded_points=points));
GRANT SELECT ON public.season_quests TO authenticated;
GRANT ALL ON public.season_quests TO service_role;
ALTER TABLE public.season_quests ENABLE ROW LEVEL SECURITY;
CREATE POLICY season_quests_read ON public.season_quests FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()) AND ((user_id=auth.uid() AND ((quest_kind='preflight' AND EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=trip_id AND n.week_number=night_week AND NOT n.skipped AND (n.week_number=(SELECT min(week_number) FROM public.game_nights WHERE trip_id=trip_id AND NOT skipped) OR EXISTS(SELECT 1 FROM public.game_nights prev WHERE prev.trip_id=trip_id AND NOT prev.skipped AND prev.week_number<n.week_number AND prev.starts_at+interval '3 hours 30 minutes'<=now() AND NOT EXISTS(SELECT 1 FROM public.game_nights x WHERE x.trip_id=trip_id AND NOT x.skipped AND x.week_number>prev.week_number AND x.week_number<n.week_number)))) AND now()>=(SELECT trip_private.season_start(trip_id)::timestamp AT TIME ZONE t.home_timezone FROM public.trips t WHERE t.id=trip_id)) OR (quest_kind='carry_on' AND EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=trip_id AND NOT n.skipped AND n.week_number=(SELECT max(week_number) FROM public.game_nights WHERE trip_id=trip_id AND NOT skipped) AND n.starts_at+interval '3 hours 30 minutes'<=now())))) OR (trip_private.is_leader(trip_id) AND status='pending')));
CREATE UNIQUE INDEX season_quests_night_unique ON public.season_quests(trip_id,user_id,night_week) WHERE quest_kind='preflight';
CREATE UNIQUE INDEX season_quests_carry_unique ON public.season_quests(trip_id,user_id) WHERE quest_kind='carry_on';
CREATE OR REPLACE FUNCTION trip_private.touch_season_quest() RETURNS trigger LANGUAGE plpgsql SET search_path='public' AS $$ BEGIN NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER season_quest_updated BEFORE UPDATE ON public.season_quests FOR EACH ROW EXECUTE FUNCTION trip_private.touch_season_quest();
ALTER TABLE public.season_settings ADD COLUMN carry_on_meetup_at timestamptz, ADD COLUMN carry_on_meetup_place text;
CREATE OR REPLACE FUNCTION trip_private.ensure_season_quests(p_trip uuid,p_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE t public.trips; n record; v_count int; v_i int:=0; v_legacy int; v_budget int; v_points int; v_pool int; v_card public.security_missions; v_dest text; BEGIN
 IF auth.uid() IS DISTINCT FROM p_user OR NOT trip_private.is_trip_member(p_trip,p_user) THEN RAISE EXCEPTION 'Only approved members can see quests'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip; IF NOT FOUND THEN RAISE EXCEPTION 'Trip not found'; END IF;
 IF now() < (trip_private.season_start(p_trip)::timestamp AT TIME ZONE t.home_timezone) THEN RETURN; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(p_trip::text||p_user::text||'quests'));
 SELECT count(*) INTO v_count FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped;
 SELECT coalesce(sum(points),0)::int INTO v_legacy FROM public.mission_claims WHERE trip_id=p_trip AND user_id=p_user AND phase='checkin' AND status IN ('pending','released');
 v_budget:=greatest(0,least(12,greatest(10,v_count))-v_legacy);
 SELECT count(*) INTO v_pool FROM public.security_missions WHERE kind='checkin' AND trip_id IS NULL;
 v_dest:=coalesce(nullif(t.destination,''),nullif(t.at_home_pack,''),'your destination');
 FOR n IN SELECT week_number,starts_at FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped ORDER BY week_number LOOP
  v_i:=v_i+1;
  IF v_i>1 AND NOT EXISTS(SELECT 1 FROM public.game_nights prev WHERE prev.trip_id=p_trip AND NOT prev.skipped AND prev.week_number<n.week_number AND prev.starts_at+interval '3 hours 30 minutes'<=now() AND NOT EXISTS(SELECT 1 FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped AND x.week_number>prev.week_number AND x.week_number<n.week_number)) THEN EXIT; END IF;
  IF v_pool<1 THEN EXIT; END IF;
  SELECT * INTO v_card FROM public.security_missions WHERE kind='checkin' AND trip_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.season_quests existing WHERE existing.trip_id=p_trip AND existing.user_id=p_user AND existing.title=replace(security_missions.title,'{destination}',v_dest)) ORDER BY md5(id::text||p_trip::text||p_user::text||v_i::text) LIMIT 1;
  IF NOT FOUND THEN EXIT; END IF;
  v_points:=CASE WHEN v_count>10 THEN 1 ELSE 10/v_count+CASE WHEN v_i<=10%v_count THEN 1 ELSE 0 END END;
  v_points:=greatest(0,least(v_points,v_budget)); v_budget:=greatest(0,v_budget-v_points);
  INSERT INTO public.season_quests(trip_id,user_id,quest_kind,night_week,title,mission_text,backstory,keywords,points) VALUES(p_trip,p_user,'preflight',n.week_number,replace(coalesce(v_card.title,'Discover the destination'),'{destination}',v_dest),replace(v_card.text,'{destination}',v_dest),replace(coalesce(v_card.backstory,''),'{destination}',v_dest),ARRAY(SELECT replace(k,'{destination}',v_dest) FROM unnest(v_card.keywords) k),v_points) ON CONFLICT DO NOTHING;
 END LOOP;
 IF t.kind IS DISTINCT FROM 'at_home' AND v_count>0 AND EXISTS(SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped AND week_number=(SELECT max(week_number) FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped) AND starts_at+interval '3 hours 30 minutes'<=now()) THEN
  SELECT * INTO v_card FROM public.security_missions WHERE kind='checkin' AND trip_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.season_quests existing WHERE existing.trip_id=p_trip AND existing.user_id=p_user AND existing.title=replace(security_missions.title,'{destination}',v_dest)) ORDER BY md5(id::text||p_trip::text||p_user::text||'carry') LIMIT 1;
  IF FOUND THEN INSERT INTO public.season_quests(trip_id,user_id,quest_kind,title,mission_text,backstory,keywords,points) VALUES(p_trip,p_user,'carry_on',replace(v_card.title,'{destination}',v_dest),replace(v_card.text,'{destination}',v_dest),replace(coalesce(v_card.backstory,''),'{destination}',v_dest),ARRAY(SELECT replace(k,'{destination}',v_dest) FROM unnest(v_card.keywords) k),5) ON CONFLICT DO NOTHING; END IF;
 END IF;
 END $$;
CREATE OR REPLACE FUNCTION trip_private.season_quest_current(p_trip uuid) RETURNS TABLE(id uuid,user_id uuid,kind text,night_week integer,title text,mission_text text,backstory text,keywords text[],points integer,status text,starts_at timestamptz,place text,total integer,completed integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ BEGIN
 PERFORM trip_private.ensure_season_quests(p_trip,auth.uid());
 RETURN QUERY SELECT q.id,q.user_id,q.quest_kind,q.night_week,q.title,q.mission_text,q.backstory,q.keywords,q.points,q.status,CASE WHEN q.quest_kind='carry_on' THEN ss.carry_on_meetup_at ELSE n.starts_at END,CASE WHEN q.quest_kind='carry_on' THEN ss.carry_on_meetup_place ELSE 'Video call' END,(SELECT count(*)::int FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped),(SELECT count(*)::int FROM public.season_quests x WHERE x.trip_id=p_trip AND x.user_id=auth.uid() AND x.quest_kind='preflight' AND x.status='approved') FROM public.season_quests q LEFT JOIN public.game_nights n ON n.trip_id=q.trip_id AND n.week_number=q.night_week LEFT JOIN public.season_settings ss ON ss.trip_id=q.trip_id AND ss.season='trip' WHERE q.trip_id=p_trip AND q.user_id=auth.uid() AND (q.quest_kind='carry_on' OR NOT n.skipped) ORDER BY CASE WHEN q.status IN ('new','declined','pending') THEN 0 ELSE 1 END,q.created_at DESC LIMIT 1;
 END $$;
CREATE OR REPLACE FUNCTION public.season_quest_current(p_trip uuid) RETURNS TABLE(id uuid,user_id uuid,kind text,night_week integer,title text,mission_text text,backstory text,keywords text[],points integer,status text,starts_at timestamptz,place text,total integer,completed integer) LANGUAGE sql SET search_path='public' AS $$ SELECT * FROM trip_private.season_quest_current(p_trip) $$;
CREATE OR REPLACE FUNCTION trip_private.season_quest_review(p_trip uuid) RETURNS TABLE(id uuid,user_id uuid,kind text,title text,points integer,status text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ BEGIN IF NOT trip_private.is_leader(p_trip) OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Only leaders can review quests'; END IF; RETURN QUERY SELECT q.id,q.user_id,q.quest_kind,q.title,q.points,q.status FROM public.season_quests q WHERE q.trip_id=p_trip AND q.status='pending' ORDER BY q.presented_at; END $$;
CREATE OR REPLACE FUNCTION public.season_quest_review(p_trip uuid) RETURNS TABLE(id uuid,user_id uuid,kind text,title text,points integer,status text) LANGUAGE sql SET search_path='public' AS $$ SELECT * FROM trip_private.season_quest_review(p_trip) $$;
CREATE OR REPLACE FUNCTION trip_private.season_quest_action(p_trip uuid,p_quest uuid,p_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE q public.season_quests; n public.game_nights; t public.trips; ss public.season_settings; BEGIN
 IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 SELECT * INTO q FROM public.season_quests WHERE id=p_quest AND trip_id=p_trip FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Quest not found'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF q.quest_kind='preflight' THEN SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=q.night_week AND NOT skipped; IF NOT FOUND THEN RAISE EXCEPTION 'This night was skipped'; END IF; IF p_action IN ('approve','decline') AND NOT (trip_private.night_open(p_trip,q.night_week) OR now()>=n.starts_at) THEN RAISE EXCEPTION 'Present this quest on game night'; END IF;
 ELSE SELECT * INTO ss FROM public.season_settings WHERE trip_id=p_trip AND season='trip'; IF ss.carry_on_meetup_at IS NULL OR now()<ss.carry_on_meetup_at OR (now() AT TIME ZONE t.trip_timezone)::date NOT BETWEEN t.start_date AND t.end_date THEN RAISE EXCEPTION 'The Carry-On meet-up must happen during the Trip'; END IF; END IF;
 IF p_action='complete' THEN IF q.user_id<>auth.uid() OR q.status NOT IN ('new','declined') THEN RAISE EXCEPTION 'Only your open quest can be marked done'; END IF; UPDATE public.season_quests SET status='pending',presented_at=now() WHERE id=p_quest AND trip_id=p_trip;
 ELSIF p_action IN ('approve','decline') THEN IF NOT trip_private.is_leader(p_trip) OR q.user_id=auth.uid() THEN RAISE EXCEPTION 'Another Captain or Co-Captain must review this quest'; END IF; IF q.status<>'pending' THEN RAISE EXCEPTION 'Quest is not waiting for review'; END IF; IF p_action='approve' THEN IF q.quest_kind='preflight' AND EXISTS(SELECT 1 FROM public.season_champions WHERE trip_id=p_trip AND season='game') THEN RAISE EXCEPTION 'The Pre-Flight crown is already final'; END IF; UPDATE public.season_quests SET status='approved',approved_at=now(),approved_by=auth.uid(),awarded_points=points WHERE id=p_quest AND trip_id=p_trip; ELSE UPDATE public.season_quests SET status='declined',presented_at=NULL WHERE id=p_quest AND trip_id=p_trip; END IF;
 ELSE RAISE EXCEPTION 'Unknown quest action'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.season_quest_action(p_trip uuid,p_quest uuid,p_action text) RETURNS void LANGUAGE sql SET search_path='public' AS $$ SELECT trip_private.season_quest_action(p_trip,p_quest,p_action) $$;
CREATE OR REPLACE FUNCTION trip_private.season_quest_approve_all(p_trip uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE r record; v_count integer:=0; BEGIN IF NOT trip_private.is_leader(p_trip) OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Only leaders can approve quests'; END IF; FOR r IN SELECT id FROM public.season_quests WHERE trip_id=p_trip AND status='pending' AND user_id<>auth.uid() ORDER BY presented_at FOR UPDATE LOOP PERFORM trip_private.season_quest_action(p_trip,r.id,'approve'); v_count:=v_count+1; END LOOP; RETURN v_count; END $$;
CREATE OR REPLACE FUNCTION public.season_quest_approve_all(p_trip uuid) RETURNS integer LANGUAGE sql SET search_path='public' AS $$ SELECT trip_private.season_quest_approve_all(p_trip) $$;
CREATE OR REPLACE FUNCTION trip_private.set_carry_on_meetup(p_trip uuid,p_at timestamptz,p_place text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE t public.trips; BEGIN IF NOT trip_private.is_captain(p_trip) OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Only the Captain can schedule the meet-up'; END IF; SELECT * INTO t FROM public.trips WHERE id=p_trip; IF t.kind='at_home' OR p_at IS NULL OR p_place IS NULL OR length(trim(p_place)) NOT BETWEEN 2 AND 160 OR (p_at AT TIME ZONE t.trip_timezone)::date NOT BETWEEN t.start_date AND t.end_date THEN RAISE EXCEPTION 'Choose a time and place during the Trip'; END IF; IF NOT EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND NOT n.skipped HAVING p_at>max(n.starts_at)+interval '3 hours 30 minutes') THEN RAISE EXCEPTION 'Schedule the meet-up after Final Call Night'; END IF; INSERT INTO public.season_settings(trip_id,season,carry_on_meetup_at,carry_on_meetup_place) VALUES(p_trip,'trip',p_at,trim(p_place)) ON CONFLICT(trip_id,season) DO UPDATE SET carry_on_meetup_at=excluded.carry_on_meetup_at,carry_on_meetup_place=excluded.carry_on_meetup_place WHERE season_settings.trip_id=p_trip AND season_settings.season='trip'; END $$;
CREATE OR REPLACE FUNCTION public.set_carry_on_meetup(p_trip uuid,p_at timestamptz,p_place text) RETURNS void LANGUAGE sql SET search_path='public' AS $$ SELECT trip_private.set_carry_on_meetup(p_trip,p_at,p_place) $$;
CREATE OR REPLACE FUNCTION trip_private.season_quest_bonus(p_trip uuid,p_kind text) RETURNS TABLE(user_id uuid,points integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='public' AS $$ BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF; IF p_kind NOT IN ('preflight','carry_on') THEN RAISE EXCEPTION 'Unknown quest kind'; END IF; RETURN QUERY SELECT m.user_id,CASE WHEN p_kind='carry_on' THEN least(5,coalesce(sum(q.awarded_points),0))::int ELSE least(least(12,greatest(10,(SELECT count(*)::int FROM public.game_nights n WHERE n.trip_id=p_trip AND NOT n.skipped))),coalesce(sum(q.awarded_points),0)+(SELECT coalesce(sum(c.points),0) FROM public.mission_claims c WHERE c.trip_id=p_trip AND c.user_id=m.user_id AND c.phase='checkin' AND c.status='released'))::int END FROM public.trip_members m LEFT JOIN public.season_quests q ON q.trip_id=m.trip_id AND q.user_id=m.user_id AND q.quest_kind=p_kind AND q.status='approved' WHERE m.trip_id=p_trip AND m.status='approved' GROUP BY m.user_id; END $$;
CREATE OR REPLACE FUNCTION trip_private.mission_bonus(p_trip uuid) RETURNS TABLE(user_id uuid,points integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='public' AS $$ WITH q AS (SELECT * FROM trip_private.season_quest_bonus(p_trip,'preflight')), other_bonus AS (SELECT c.user_id,least(12,sum(c.points))::int pts FROM public.mission_claims c WHERE c.trip_id=p_trip AND c.phase<>'checkin' AND c.status='released' GROUP BY c.user_id,c.phase) SELECT q.user_id,(q.points+coalesce((SELECT sum(o.pts) FROM other_bonus o WHERE o.user_id=q.user_id),0))::int FROM q $$;
CREATE OR REPLACE FUNCTION trip_private.trip_season_score(p_trip uuid) RETURNS TABLE(user_id uuid,stamps integer,today_stamps integer,max_stamps integer,score integer,carry_on integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='public' AS $$ SELECT s.user_id,s.stamps,s.today_stamps,s.max_stamps,least(100,greatest(0,(CASE WHEN s.max_stamps>0 THEN round(s.stamps*100.0/s.max_stamps)::int ELSE 0 END)+coalesce(b.points,0)))::int,coalesce(b.points,0) FROM trip_private.trip_season(p_trip) s LEFT JOIN trip_private.season_quest_bonus(p_trip,'carry_on') b ON b.user_id=s.user_id $$;
CREATE OR REPLACE FUNCTION public.trip_season_score(p_trip uuid) RETURNS TABLE(user_id uuid,stamps integer,today_stamps integer,max_stamps integer,score integer,carry_on integer) LANGUAGE sql SET search_path='public' AS $$ SELECT * FROM trip_private.trip_season_score(p_trip) $$;
CREATE OR REPLACE FUNCTION trip_private.home_day_scores(p_trip uuid) RETURNS TABLE(user_id uuid,points integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='public' AS $$ BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this experience first'; END IF; RETURN QUERY SELECT m.user_id,(coalesce(sum((CASE WHEN r.completed_at IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN r.presented_at IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN r.voted_at IS NOT NULL THEN 1 ELSE 0 END)) FILTER (WHERE s.revealed_at IS NOT NULL),0)+coalesce(q.points,0))::int FROM public.trip_members m LEFT JOIN public.home_day_sessions s ON s.trip_id=m.trip_id LEFT JOIN public.home_day_results r ON r.session_id=s.id AND r.user_id=m.user_id LEFT JOIN trip_private.season_quest_bonus(p_trip,'preflight') q ON q.user_id=m.user_id WHERE m.trip_id=p_trip AND m.status='approved' GROUP BY m.user_id,q.points ORDER BY 2 DESC,m.user_id; END $$;
CREATE OR REPLACE FUNCTION trip_private.at_home_mvp(p_trip uuid) RETURNS TABLE(user_id uuid,points integer,wins integer,votes integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='public' AS $$ DECLARE t public.trips; v_today date; BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this experience first'; END IF; SELECT * INTO t FROM public.trips WHERE id=p_trip; SELECT p.today INTO v_today FROM trip_private.at_home_plan(p_trip) p LIMIT 1; IF t.ended_at IS NULL AND coalesce(v_today,current_date)<t.end_date THEN RETURN; END IF; RETURN QUERY WITH w AS (SELECT a.winner_id u,count(*)::int n FROM public.at_home_activities a WHERE a.trip_id=p_trip AND a.winner_id IS NOT NULL GROUP BY 1),v AS (SELECT vt.target_id u,count(*)::int n FROM public.at_home_votes vt JOIN public.at_home_activities a ON a.id=vt.activity_id AND a.trip_id=p_trip AND a.revealed_at IS NOT NULL GROUP BY 1) SELECT m.user_id,(coalesce(w.n,0)*3+coalesce(v.n,0)+coalesce(q.points,0))::int,coalesce(w.n,0),coalesce(v.n,0) FROM public.trip_members m LEFT JOIN w ON w.u=m.user_id LEFT JOIN v ON v.u=m.user_id LEFT JOIN trip_private.season_quest_bonus(p_trip,'preflight') q ON q.user_id=m.user_id WHERE m.trip_id=p_trip AND m.status='approved' ORDER BY 2 DESC; END $$;
CREATE OR REPLACE FUNCTION trip_private.finalize_season(p_trip uuid,p_season text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE st public.season_settings; v_at timestamptz; BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF; IF NOT coalesce((SELECT season_scoring FROM public.trips WHERE id=p_trip),true) THEN RETURN; END IF; SELECT * INTO st FROM public.season_settings WHERE trip_id=p_trip AND season=p_season; IF NOT FOUND THEN RETURN; END IF; v_at:=trip_private.effective_crowning(p_trip,p_season); IF v_at IS NULL OR v_at>now() THEN RETURN; END IF; PERFORM pg_advisory_xact_lock(hashtext('crown'||p_trip::text||p_season)); IF EXISTS(SELECT 1 FROM public.season_champions WHERE trip_id=p_trip AND season=p_season) THEN RETURN; END IF; IF p_season='trip' THEN INSERT INTO public.season_champions(trip_id,season,user_id,score,stamps) WITH r AS (SELECT user_id,stamps,score FROM trip_private.trip_season_score(p_trip)) SELECT p_trip,'trip',r.user_id,r.score,r.stamps FROM r WHERE r.stamps>0 AND (SELECT count(*) FROM r o WHERE (o.score,o.stamps)>(r.score,r.stamps))<st.winners; ELSE INSERT INTO public.season_champions(trip_id,season,user_id,score,stamps,tie_ids) WITH r AS (SELECT * FROM trip_private.game_board(p_trip) WHERE stamps>0), k AS (SELECT r.*,(SELECT count(*) FROM r o WHERE (o.score,o.attended)>(r.score,r.attended)) ahead,(SELECT array_agg(o.user_id ORDER BY o.user_id) FROM r o WHERE o.score=r.score AND o.attended=r.attended) grp,row_number() OVER (ORDER BY r.score DESC,r.attended DESC,random()) rn FROM r) SELECT p_trip,'game',k.user_id,k.score,k.stamps,CASE WHEN cardinality(k.grp)>1 AND k.ahead+cardinality(k.grp)>st.winners THEN k.grp END FROM k WHERE k.rn<=st.winners; END IF; END $$;
REVOKE ALL ON FUNCTION public.season_quest_current(uuid),public.season_quest_review(uuid),public.season_quest_action(uuid,uuid,text),public.season_quest_approve_all(uuid),public.set_carry_on_meetup(uuid,timestamptz,text),public.trip_season_score(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.season_quest_current(uuid),public.season_quest_review(uuid),public.season_quest_action(uuid,uuid,text),public.season_quest_approve_all(uuid),public.set_carry_on_meetup(uuid,timestamptz,text),public.trip_season_score(uuid) TO authenticated;
REVOKE ALL ON FUNCTION trip_private.ensure_season_quests(uuid,uuid),trip_private.season_quest_current(uuid),trip_private.season_quest_review(uuid),trip_private.season_quest_action(uuid,uuid,text),trip_private.season_quest_approve_all(uuid),trip_private.season_quest_bonus(uuid,text),trip_private.set_carry_on_meetup(uuid,timestamptz,text),trip_private.trip_season_score(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION trip_private.ensure_season_quests(uuid,uuid),trip_private.season_quest_current(uuid),trip_private.season_quest_review(uuid),trip_private.season_quest_action(uuid,uuid,text),trip_private.season_quest_approve_all(uuid),trip_private.season_quest_bonus(uuid,text),trip_private.set_carry_on_meetup(uuid,timestamptz,text),trip_private.trip_season_score(uuid) TO authenticated,service_role;